    /**
     * @brief メインのデータ処理を実行する
     */
    void process_data() {
        vector<string> files = get_files();
        size_t total_files = files.size();

        // 使用可能なスレッド数を取得し、ワークロードを分割
        vector<thread> threads;
        mutex mtx;  // スレッド間で共有される뮤セクション

        // 非同期処理用のワーカー関数
        auto worker = [&](size_t start, size_t end) {
            for (size_t i = start; i < end; ++i) {
                string filename = files[i];
                lock_guard<mutex> lg(mtx);  // ロックを取得し、排他処理を行う
                process_file(filename);
            }
        };

        size_t num_threads = thread::hardware_concurrency();
        size_t step = total_files / num_threads + 1;

        // 各スレッドにワークロードを割り当てる
        for (size_t i = 0; i < num_threads; ++i) {
            threads.push_back(thread(worker, i * step, min((i + 1) * step, total_files)));
        }

        // 全てのスレッドが終了するまで待つ
        for (auto& t : threads) {
            if (t.joinable()) {
                t.join();
            }
        }
    }

